(541, 'hx-541', '', 'email', 'Email', 'Breach Data Classes Exposed', 'high', '', 'planned', 'Which kinds of data leaked with the address in each known breach (passwords, phone numbers, dates of birth). Tool: HaveIBeenPwned. Proposed confidence 92/100. Needs the person''s consent (MPC-11307).', ''),
(542, 'hx-542', '', 'email', 'Email', 'Leaked Credentials and Password Hashes', 'high', '', 'planned', 'Whether a password or password hash tied to the address sits in leaked databases. Tool: Dehashed. Proposed confidence 70/100. Never store or show the password or hash; keep only yes/no, count and source name. Needs consent (MPC-11307).', ''),
(543, 'hx-543', '', 'email', 'Email', 'Breach-Linked Identity Details', 'high', '', 'planned', 'Name, phone, address, IP or username that leaked in the same record as the email. Tool: Dehashed. Proposed confidence 62/100. Needs consent (MPC-11307).', ''),
(544, 'hx-544', '', '', 'Cross-Channel / General', 'Username Reuse Across Platforms', 'medium', '', 'planned', 'The same username registered on many sites, linking separate accounts into one profile. Tools: Sherlock, WhatsMyName. Proposed confidence 55/100 for a single-tool hit. Needs consent (MPC-11307).', ''),
(545, 'hx-545', '', '', 'Cross-Channel / General', 'Google Account Footprint', 'high', '', 'planned', 'Whether the address is a Google account and what is public on it: account ID, name, photo, Maps reviews and photos, YouTube channel, calendar. Tool: GHunt (needs a signed-in Google session on our side). Proposed confidence 78/100. Needs consent (MPC-11307).', ''),
(546, 'hx-546', '', 'email', 'Email', 'Email Registration Footprint', 'medium', '', 'planned', 'The services where this address already has an account (around 120 sites checked). Tool: Holehe. Proposed confidence 66/100. Raise risk to High if a dating, adult, health or finance site is found. Needs consent (MPC-11307).', ''),
